        int DEFM = scanner.nextInt();

        int h = scanner.nextInt();
        int a = scanner.nextInt();
        int d = scanner.nextInt();

        int minCost = Integer.MAX_VALUE;

        // Try all possible additional HP, ATK, DEF
        // HP can go up to some reasonable limit
        // ATK can go up to some reasonable limit
        // DEF can go up to some reasonable limit

        // The monster's HP is at most 100, so Yang needs at most 100 hits if damage is 1
        // But with upgrades, we need to consider various combinations

        // Let's think about bounds:
        // Additional HP: 0 to 1000 (since prices are up to 100, and we want to be safe)
        // Additional ATK: 0 to 100 (since DEFM is at most 100, and HPM is at most 100)
        // Additional DEF: 0 to 100 (since ATKM is at most 100)

        for (int addHP = 0; addHP <= 1000; addHP++) {
            for (int addATK = 0; addATK <= 100; addATK++) {
                for (int addDEF = 0; addDEF <= 100; addDEF++) {
                    int totalHP = HPY + addHP;
                    int totalATK = ATKY + addATK;
                    int totalDEF = DEFY + addDEF;

                    // Check if Yang can win
                    if (canWin(totalHP, totalATK, totalDEF, HPM, ATKM, DEFM)) {
                        int cost = addHP * h + addATK * a + addDEF * d;
                        if (cost < minCost) {
                            minCost = cost;
                        }
                    }
                }
            }
        }

        System.out.println(minCost);
    }

    static boolean canWin(int HPY, int ATKY, int DEFY, int HPM, int ATKM, int DEFM) {
        // Damage Yang deals to monster per second
        int damageToMonster = Math.max(0, ATKY - DEFM);
        // Damage monster deals to Yang per second
        int damageToYang = Math.max(0, ATKM - DEFY);

        // If Yang can't deal any damage, he can't win
        if (damageToMonster <= 0) {
            return false;
        }

        // Number of seconds needed to kill monster
        int secondsToKill = (HPM + damageToMonster - 1) / damageToMonster;

        // Yang's HP after the battle
        // Both attack simultaneously each second
        // After secondsToKill seconds, monster is dead
        // Yang takes damageToYang damage each second
        int yangHPAfter = HPY - secondsToKill * damageToYang;

        // Yang wins if monster HP <= 0 and Yang HP > 0
        // Monster HP becomes 0 after secondsToKill seconds
        // Yang HP must be > 0 at that time
        return yangHPAfter > 0;
    }
}
