        // Max addATK to consider: if we buy enough ATK to kill in 1 turn, that's the best case for HP requirement.
        // Any more ATK doesn't reduce turns below 1.
        // So max addATK = max(0, HPM + DEFM - ATKY).
        // But wait, what if HPM is large? HPM <= 100.
        // So addATK up to 200 is safe.

        int maxAddATK = 200; // Safe upper bound since HPM, DEFM <= 100
        int maxAddDEF = 200; // Safe upper bound since ATKM <= 100, if DEFY + addDEF >= ATKM, damage is 0.

        for (int addATK = 0; addATK <= maxAddATK; addATK++) {
            int newATK = ATKY + addATK;
            if (newATK <= DEFM) {
                continue; // Cannot kill monster
            }

            int damagePerTurn = newATK - DEFM;
            int turnsToKill = (HPM + damagePerTurn - 1) / damagePerTurn; // Ceil division

            for (int addDEF = 0; addDEF <= maxAddDEF; addDEF++) {
                int newDEF = DEFY + addDEF;
                int damageTakenPerTurn = Math.max(0, ATKM - newDEF);

                // Total damage Yang takes
                long totalDamage = (long) turnsToKill * damageTakenPerTurn;

                // Yang needs HP > totalDamage
                // So newHP must be at least totalDamage + 1
                long requiredHP = totalDamage + 1;

                if (HPY >= requiredHP) {
                    // No HP needed
                    int cost = addATK * a + addDEF * d;
                    if (cost < minCost) {
                        minCost = cost;
                    }
                } else {
                    int addHP = (int) (requiredHP - HPY);
                    int cost = addATK * a + addDEF * d + addHP * h;
                    if (cost < minCost) {
                        minCost = cost;
                    }
                }
            }
        }

        // It is guaranteed that there is a solution.
        // If minCost is still MAX_VALUE, something is wrong, but problem guarantees solvability.
        System.out.println(minCost);
    }
