        int priceD = scanner.nextInt();

        int minCost = Integer.MAX_VALUE;

        // We need to determine the maximum number of turns Yang needs to survive.
        // The number of turns Yang needs to kill the monster depends on his ATK.
        // Let T be the number of turns.
        // Yang kills monster in T turns if: T * max(0, atky - defm) >= hpm
        // If atky <= defm, he can never kill the monster (unless hpm is 0, but hpm >= 1).

        // Monster deals damage to Yang each turn: dmg = max(0, atkm - defy)
        // Yang survives T turns if: hpy > (T - 1) * dmg  (since he must be alive after T-th turn when monster dies)
        // Actually, the condition is: After T turns, Monster HP <= 0 AND Yang HP > 0.
        // Yang's HP after T turns = hpy - T * dmg.
        // We need hpy - T * dmg > 0 => hpy > T * dmg.

        // Let's iterate over possible enhancements.
        // Since inputs are small (<= 100), we can iterate over possible values of ATK and DEF.
        // Max ATK needed: To kill monster in 1 turn, atky - defm >= hpm => atky >= hpm + defm.
        // hpm, defm <= 100, so atky <= 200.
        // Min ATK: atky.

        // Max DEF needed: To reduce damage to 0, defy >= atkm.
        // atkm <= 100, so defy <= 100.
        // Min DEF: defy.

        // Max HP needed: If dmg > 0, and we want to survive T turns, hpy > T * dmg.
        // T can be at most hpm (if atky - defm = 1). hpm <= 100.
        // dmg can be at most atkm (if defy=0, but defy>=1, so dmg <= atkm-1 <= 99).
        // So hpy > 100 * 99 = 9900.
        // However, we don't need to iterate HP up to 9900 blindly.
        // For a fixed ATK and DEF, we can calculate the minimum HP required.

        for (int newAtk = atky; newAtk <= hpm + defm; newAtk++) {
            // If newAtk <= defm, damage is 0, infinite turns, impossible to kill.
            if (newAtk <= defm) {
                continue;
            }

            int damageToMonster = newAtk - defm;
            // Turns needed to kill monster
            int turnsNeeded = (hpm + damageToMonster - 1) / damageToMonster;

            for (int newDef = defy; newDef <= atkm; newDef++) {
                int damageToYang = Math.max(0, atkm - newDef);

                // Calculate minimum HP required
                // Yang must have HP > turnsNeeded * damageToYang
                // So minHp = turnsNeeded * damageToYang + 1
                int minHpRequired = turnsNeeded * damageToYang + 1;

                // If current HP is already sufficient, cost for HP is 0.
                // Otherwise, buy (minHpRequired - hpy) HP.
                int hpToBuy = Math.max(0, minHpRequired - hpy);
                int atkToBuy = newAtk - atky;
                int defToBuy = newDef - defy;

                int cost = hpToBuy * priceH + atkToBuy * priceA + defToBuy * priceD;

                if (cost < minCost) {
                    minCost = cost;
                }
            }
        }

        // Edge case: What if Yang can already kill the monster in 0 turns? No, hpm >= 1.
        // What if the loop doesn't find a solution? 
        // The loop covers newAtk up to hpm + defm.
        // If newAtk = hpm + defm, damageToMonster = hpm. turnsNeeded = 1.
        // This is always a valid solution (buy enough ATK to one-shot).
        // So minCost will be updated.

        System.out.println(minCost);
    }
