                    // So we just need initial HP > 0, which is always true (>=1).
                    // Cost for ATK and DEF
                    int costAtk = (newAtk - atkY) * costA;
                    int costDef = (newDef - defY) * costD;
                    int totalCost = costAtk + costDef;
                    if (totalCost < minCost) {
                        minCost = totalCost;
                    }
                    continue;
                }

                // Yang takes damageToYang per turn.
                // After 'turns' seconds, monster dies.
                // Yang's HP after 'turns' seconds: hpY + addHp - turns * damageToYang
                // We need this to be > 0.
                // hpY + addHp > turns * damageToYang
                // addHp > turns * damageToYang - hpY
                // addHp >= turns * damageToYang - hpY + 1
                // Also addHp >= 0

                int requiredHp = turns * damageToYang - hpY + 1;
                if (requiredHp < 0) {
                    requiredHp = 0;
                }

                int costHp = requiredHp * costH;
                int costAtk = (newAtk - atkY) * costA;
                int costDef = (newDef - defY) * costD;
                int totalCost = costHp + costAtk + costDef;

                if (totalCost < minCost) {
                    minCost = totalCost;
                }
            }
        }

        System.out.println(minCost);
    }
