        // Maximum additional ATK: we need ATKY - DEFM > 0, so ATKY > DEFM. DEFM <= 100, so ATKY up to 200 should be enough.
        // Maximum additional DEF: we need DEFY >= ATKM to make monster unable to hurt, or just reduce damage. ATKM <= 100, so DEFY up to 200 should be enough.

        // Let's be safe and iterate:
        // additional HP from 0 to 10000
        // additional ATK from 0 to 200
        // additional DEF from 0 to 200

        for (int addHP = 0; addHP <= 10000; addHP++) {
            for (int addATK = 0; addATK <= 200; addATK++) {
                for (int addDEF = 0; addDEF <= 200; addDEF++) {
                    long cost = (long) addHP * h + (long) addATK * a + (long) addDEF * d;
                    if (cost >= minCost) continue;

                    int newHPY = HPY + addHP;
                    int newATKY = ATKY + addATK;
                    int newDEFY = DEFY + addDEF;

                    // Check if Yang can win
                    if (newATKY <= DEFM) {
                        // Monster never dies
                        continue;
                    }

                    int damageToMonster = newATKY - DEFM;
                    int damageToYang = Math.max(0, ATKM - newDEFY);

                    // Turns to kill monster
                    int turnsToKill = (HPM + damageToMonster - 1) / damageToMonster;

                    if (damageToYang == 0) {
                        // Monster can't hurt Yang, so Yang always wins if he can kill monster
                        minCost = Math.min(minCost, cost);
                    } else {
                        // Yang HP after turnsToKill turns
                        int yangHPAfter = newHPY - turnsToKill * damageToYang;
                        if (yangHPAfter > 0) {
                            minCost = Math.min(minCost, cost);
                        }
                    }
                }
            }
        }

        System.out.println(minCost);
    }
}
